/**
 * Alerts and Monitoring Dashboard Component
 * 
 * Provides comprehensive monitoring and alerting management interface
 * including active alerts, alert rules, system health, and metrics.
 * 
 * Requirements: 8.1, 8.3
 */

import React, { useState, useEffect } from 'react';
import './AlertsMonitoring.css';

// Types
interface Alert {
  alert_id: string;
  rule_id: string;
  rule_name: string;
  message: string;
  severity: 'info' | 'warning' | 'critical';
  status: 'active' | 'resolved' | 'suppressed';
  metric_name: string;
  metric_value: number;
  threshold: number;
  triggered_at: string;
  resolved_at?: string;
  tags: Record<string, string>;
}

interface AlertRule {
  rule_id: string;
  name: string;
  description: string;
  metric_name: string;
  condition: string;
  threshold: number;
  severity: 'info' | 'warning' | 'critical';
  duration_minutes: number;
  enabled: boolean;
  tags: Record<string, string>;
}

interface SystemMetrics {
  timestamp: string;
  cpu_percent: number;
  memory_percent: number;
  memory_available_gb: number;
  disk_usage_percent: number;
  disk_free_gb: number;
  active_connections: number;
  response_time_avg_ms: number;
  error_rate_percent: number;
}

interface ServiceHealth {
  service_name: string;
  status: 'healthy' | 'degraded' | 'unhealthy';
  last_check: string;
  response_time_ms?: number;
  error_message?: string;
  uptime_percent?: number;
}

interface AlertSummary {
  timestamp: string;
  monitoring_status: 'running' | 'stopped';
  total_rules: number;
  enabled_rules: number;
  active_alerts: number;
  active_by_severity: {
    info: number;
    warning: number;
    critical: number;
  };
  total_channels: number;
  enabled_channels: number;
  alerts_last_24h: number;
}

interface HealthSummary {
  overall_status: 'healthy' | 'degraded' | 'unhealthy' | 'unknown';
  timestamp: string;
  system_metrics: SystemMetrics | null;
  services: Record<string, ServiceHealth>;
  uptime_status: 'running' | 'stopped';
}

// API functions
const api = {
  async getAlertSummary(): Promise<AlertSummary> {
    const response = await fetch('/api/v1/health/alerts');
    const data = await response.json();
    return data.data;
  },

  async getActiveAlerts(): Promise<Alert[]> {
    const response = await fetch('/api/v1/health/alerts/active');
    const data = await response.json();
    return data.data;
  },

  async getAlertRules(): Promise<AlertRule[]> {
    const response = await fetch('/api/v1/health/alerts/rules');
    const data = await response.json();
    return data.data;
  },

  async getHealthSummary(): Promise<HealthSummary> {
    const response = await fetch('/api/v1/health/detailed');
    const data = await response.json();
    return data.data;
  },

  async startAlertMonitoring(): Promise<void> {
    await fetch('/api/v1/health/alerts/monitoring/start', { method: 'POST' });
  },

  async stopAlertMonitoring(): Promise<void> {
    await fetch('/api/v1/health/alerts/monitoring/stop', { method: 'POST' });
  },

  async suppressAlert(ruleId: string): Promise<void> {
    await fetch(`/api/v1/health/alerts/${ruleId}/suppress`, { method: 'POST' });
  }
};

// Severity Badge Component
const SeverityBadge: React.FC<{ severity: string }> = ({ severity }) => (
  <span className={`severity-badge severity-${severity}`}>
    {severity.toUpperCase()}
  </span>
);

// Status Badge Component
const StatusBadge: React.FC<{ status: string }> = ({ status }) => (
  <span className={`status-badge status-${status}`}>
    {status.toUpperCase()}
  </span>
);

// Metric Card Component
const MetricCard: React.FC<{
  title: string;
  value: number | string;
  unit?: string;
  status?: 'good' | 'warning' | 'critical';
}> = ({ title, value, unit, status = 'good' }) => (
  <div className={`metric-card metric-${status}`}>
    <h4>{title}</h4>
    <div className="metric-value">
      {typeof value === 'number' ? value.toFixed(1) : value}
      {unit && <span className="unit">{unit}</span>}
    </div>
  </div>
);

// Alert Summary Component
const AlertSummaryCard: React.FC<{ summary: AlertSummary }> = ({ summary }) => (
  <div className="alert-summary-card">
    <h3>Alert System Overview</h3>
    <div className="summary-grid">
      <MetricCard
        title="Monitoring Status"
        value={summary.monitoring_status}
        status={summary.monitoring_status === 'running' ? 'good' : 'warning'}
      />
      <MetricCard title="Total Rules" value={summary.total_rules} />
      <MetricCard title="Enabled Rules" value={summary.enabled_rules} />
      <MetricCard
        title="Active Alerts"
        value={summary.active_alerts}
        status={summary.active_alerts > 0 ? 'warning' : 'good'}
      />
      <MetricCard
        title="Critical Alerts"
        value={summary.active_by_severity.critical}
        status={summary.active_by_severity.critical > 0 ? 'critical' : 'good'}
      />
      <MetricCard
        title="Warning Alerts"
        value={summary.active_by_severity.warning}
        status={summary.active_by_severity.warning > 0 ? 'warning' : 'good'}
      />
      <MetricCard title="Alerts (24h)" value={summary.alerts_last_24h} />
      <MetricCard title="Notification Channels" value={summary.enabled_channels} />
    </div>
  </div>
);

// System Health Component
const SystemHealthCard: React.FC<{ health: HealthSummary }> = ({ health }) => {
  const getStatusColor = (status: string) => {
    switch (status) {
      case 'healthy': return 'good';
      case 'degraded': return 'warning';
      case 'unhealthy': return 'critical';
      default: return 'warning';
    }
  };

  return (
    <div className="system-health-card">
      <h3>System Health</h3>
      <div className="health-overview">
        <MetricCard
          title="Overall Status"
          value={health.overall_status}
          status={getStatusColor(health.overall_status)}
        />
        <MetricCard
          title="Uptime Status"
          value={health.uptime_status}
          status={health.uptime_status === 'running' ? 'good' : 'warning'}
        />
      </div>

      {health.system_metrics && (
        <div className="system-metrics">
          <h4>System Metrics</h4>
          <div className="metrics-grid">
            <MetricCard
              title="CPU Usage"
              value={health.system_metrics.cpu_percent}
              unit="%"
              status={health.system_metrics.cpu_percent > 80 ? 'critical' : 
                     health.system_metrics.cpu_percent > 60 ? 'warning' : 'good'}
            />
            <MetricCard
              title="Memory Usage"
              value={health.system_metrics.memory_percent}
              unit="%"
              status={health.system_metrics.memory_percent > 85 ? 'critical' : 
                     health.system_metrics.memory_percent > 70 ? 'warning' : 'good'}
            />
            <MetricCard
              title="Disk Usage"
              value={health.system_metrics.disk_usage_percent}
              unit="%"
              status={health.system_metrics.disk_usage_percent > 90 ? 'critical' : 
                     health.system_metrics.disk_usage_percent > 80 ? 'warning' : 'good'}
            />
            <MetricCard
              title="Response Time"
              value={health.system_metrics.response_time_avg_ms}
              unit="ms"
              status={health.system_metrics.response_time_avg_ms > 1000 ? 'critical' : 
                     health.system_metrics.response_time_avg_ms > 500 ? 'warning' : 'good'}
            />
            <MetricCard
              title="Error Rate"
              value={health.system_metrics.error_rate_percent}
              unit="%"
              status={health.system_metrics.error_rate_percent > 10 ? 'critical' : 
                     health.system_metrics.error_rate_percent > 5 ? 'warning' : 'good'}
            />
            <MetricCard
              title="Active Connections"
              value={health.system_metrics.active_connections}
            />
          </div>
        </div>
      )}

      <div className="services-health">
        <h4>Services</h4>
        <div className="services-grid">
          {Object.entries(health.services).map(([name, service]) => (
            <div key={name} className={`service-card service-${service.status}`}>
              <div className="service-name">{name}</div>
              <StatusBadge status={service.status} />
              {service.response_time_ms && (
                <div className="service-metric">
                  {service.response_time_ms.toFixed(1)}ms
                </div>
              )}
              {service.error_message && (
                <div className="service-error">{service.error_message}</div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

// Active Alerts Component
const ActiveAlertsCard: React.FC<{
  alerts: Alert[];
  onSuppressAlert: (ruleId: string) => void;
}> = ({ alerts, onSuppressAlert }) => (
  <div className="active-alerts-card">
    <h3>Active Alerts</h3>
    {alerts.length === 0 ? (
      <div className="no-alerts">No active alerts</div>
    ) : (
      <div className="alerts-list">
        {alerts.map((alert) => (
          <div key={alert.alert_id} className={`alert-item alert-${alert.severity}`}>
            <div className="alert-header">
              <span className="alert-name">{alert.rule_name}</span>
              <div className="alert-badges">
                <SeverityBadge severity={alert.severity} />
                <StatusBadge status={alert.status} />
              </div>
            </div>
            <div className="alert-message">{alert.message}</div>
            <div className="alert-details">
              <span>Metric: {alert.metric_name}</span>
              <span>Value: {alert.metric_value.toFixed(2)}</span>
              <span>Threshold: {alert.threshold}</span>
              <span>Triggered: {new Date(alert.triggered_at).toLocaleString()}</span>
            </div>
            <div className="alert-actions">
              <button
                onClick={() => onSuppressAlert(alert.rule_id)}
                className="suppress-btn"
                disabled={alert.status === 'suppressed'}
              >
                {alert.status === 'suppressed' ? 'Suppressed' : 'Suppress'}
              </button>
            </div>
          </div>
        ))}
      </div>
    )}
  </div>
);

// Alert Rules Component
const AlertRulesCard: React.FC<{ rules: AlertRule[] }> = ({ rules }) => (
  <div className="alert-rules-card">
    <h3>Alert Rules</h3>
    <div className="rules-table">
      <div className="table-header">
        <div>Rule Name</div>
        <div>Metric</div>
        <div>Condition</div>
        <div>Threshold</div>
        <div>Severity</div>
        <div>Status</div>
      </div>
      {rules.map((rule) => (
        <div key={rule.rule_id} className="table-row">
          <div className="rule-name">
            <div>{rule.name}</div>
            <div className="rule-description">{rule.description}</div>
          </div>
          <div>{rule.metric_name}</div>
          <div>{rule.condition.replace('_', ' ')}</div>
          <div>{rule.threshold}</div>
          <div><SeverityBadge severity={rule.severity} /></div>
          <div>
            <span className={`enable-status ${rule.enabled ? 'enabled' : 'disabled'}`}>
              {rule.enabled ? 'Enabled' : 'Disabled'}
            </span>
          </div>
        </div>
      ))}
    </div>
  </div>
);

// Main Component
const AlertsMonitoring: React.FC = () => {
  const [alertSummary, setAlertSummary] = useState<AlertSummary | null>(null);
  const [activeAlerts, setActiveAlerts] = useState<Alert[]>([]);
  const [alertRules, setAlertRules] = useState<AlertRule[]>([]);
  const [healthSummary, setHealthSummary] = useState<HealthSummary | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'overview' | 'alerts' | 'rules' | 'health'>('overview');

  const loadData = async () => {
    try {
      setLoading(true);
      const [summary, alerts, rules, health] = await Promise.all([
        api.getAlertSummary(),
        api.getActiveAlerts(),
        api.getAlertRules(),
        api.getHealthSummary()
      ]);

      setAlertSummary(summary);
      setActiveAlerts(alerts);
      setAlertRules(rules);
      setHealthSummary(health);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load monitoring data');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
    // Refresh data every 30 seconds
    const interval = setInterval(loadData, 30000);
    return () => clearInterval(interval);
  }, []);

  const handleStartMonitoring = async () => {
    try {
      await api.startAlertMonitoring();
      await loadData();
    } catch (err) {
      setError('Failed to start monitoring');
    }
  };

  const handleStopMonitoring = async () => {
    try {
      await api.stopAlertMonitoring();
      await loadData();
    } catch (err) {
      setError('Failed to stop monitoring');
    }
  };

  const handleSuppressAlert = async (ruleId: string) => {
    try {
      await api.suppressAlert(ruleId);
      await loadData();
    } catch (err) {
      setError('Failed to suppress alert');
    }
  };

  if (loading) {
    return <div className="alerts-monitoring loading">Loading monitoring data...</div>;
  }

  if (error) {
    return (
      <div className="alerts-monitoring error">
        <div className="error-message">{error}</div>
        <button onClick={loadData} className="retry-btn">Retry</button>
      </div>
    );
  }

  return (
    <div className="alerts-monitoring">
      <div className="monitoring-header">
        <h2>Monitoring & Alerts</h2>
        <div className="header-actions">
          <button onClick={loadData} className="refresh-btn">
            Refresh
          </button>
          {alertSummary?.monitoring_status === 'running' ? (
            <button onClick={handleStopMonitoring} className="stop-btn">
              Stop Monitoring
            </button>
          ) : (
            <button onClick={handleStartMonitoring} className="start-btn">
              Start Monitoring
            </button>
          )}
        </div>
      </div>

      <div className="tab-navigation">
        {(['overview', 'alerts', 'rules', 'health'] as const).map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`tab-btn ${activeTab === tab ? 'active' : ''}`}
          >
            {tab.charAt(0).toUpperCase() + tab.slice(1)}
          </button>
        ))}
      </div>

      <div className="tab-content">
        {activeTab === 'overview' && alertSummary && (
          <div className="overview-tab">
            <AlertSummaryCard summary={alertSummary} />
            {activeAlerts.length > 0 && (
              <ActiveAlertsCard
                alerts={activeAlerts.slice(0, 5)}
                onSuppressAlert={handleSuppressAlert}
              />
            )}
          </div>
        )}

        {activeTab === 'alerts' && (
          <ActiveAlertsCard
            alerts={activeAlerts}
            onSuppressAlert={handleSuppressAlert}
          />
        )}

        {activeTab === 'rules' && (
          <AlertRulesCard rules={alertRules} />
        )}

        {activeTab === 'health' && healthSummary && (
          <SystemHealthCard health={healthSummary} />
        )}
      </div>
    </div>
  );
};

export default AlertsMonitoring;
